import { BooleanColumn, ChoiceColumn } from '@servicenow/sdk/core'
import { FlowObject, FlowArray, ActionDefinition } from '@servicenow/sdk/automation'
/**
 * Diagnostic ActionDefinition Example
 *
 * This example demonstrates various Diagnostic errors
 * - ChoiceColumn with invalid dynamicValueDefinitions
 * - Invalid array element type
 * - Dynamic value definitions are not supported
 */

ActionDefinition({
    $id: 'diagnostic-action-definition',
    name: 'diagnostic-action-definition',
    annotation: 'Diagnostic Action Definition Example',
    description: 'An example showing various Flow types for diagnostic purposes',
    category: 'Diagnostics',
    inputs: {
        // Basic column inputs
        active: BooleanColumn({
            label: 'Active',
            mandatory: true,
            default: true,
        }),
        days: FlowArray({
            label: 'Days',
            mandatory: false,
            childName: 'day_child0',
            elementType: ChoiceColumn({
                label: 'Day',
                mandatory: true,
                choices: {
                    saturday: 'Saturday',
                    sunday: 'Sunday',
                    monday: 'Monday',
                    tuesday: 'Tuesday',
                    wednesday: 'Wednesday',
                    thursday: 'Thursday',
                    friday: 'Friday',
                },
            }),
        }),

        test: ChoiceColumn({
            label: 'Day',
            mandatory: true,
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculated_value: 'state',
            },
        }),
    },
    outputs: {
        // FlowObject output
        result: FlowObject({
            label: 'Result',
            mandatory: false,
            fields: {
                status: ChoiceColumn({
                    label: 'Status',
                    mandatory: false,
                    dynamicValueDefinitions: {
                        type: 'choices_from_other_table',
                        table: 'incident',
                        field: 'state',
                    },
                }),
            },
        }),
    },
})
